<?php
namespace Ishep\Services;use PDO;use Throwable;use DomainException;use Ishep\Repositories\{PortalRepository,AuditLogRepository,RoleRepository,MemberProfileRepository};use Ishep\Support\PublicReference;
final class PortalService
{public function __construct(private PDO $db,private PortalRepository $repo,private AuditLogRepository $audits,private RoleRepository $roles,private MemberProfileRepository $profiles,private ProfileCompletionService $completion,private PortalStatus $statuses){}private function tx(callable $fn):mixed{$owned=!$this->db->inTransaction();if($owned)$this->db->beginTransaction();try{$r=$fn();if($owned)$this->db->commit();return$r;}catch(Throwable $e){if($owned&&$this->db->inTransaction())$this->db->rollBack();throw$e;}}private function permission(int $uid,string $permission):void{if(!in_array($permission,$this->roles->permissions($uid),true))throw new DomainException('You are not authorized for this portal action.');}private function text(array $in,string $key,int $min=1,int $max=5000):string{$v=trim((string)($in[$key]??''));if(mb_strlen($v)<$min||mb_strlen($v)>$max)throw new DomainException(ucwords(str_replace('_',' ',$key)).' is required and must be within '.$max.' characters.');return$v;}private function date(string $v,string $label):string{$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new DomainException($label.' must be a valid date.');return$v;}
public function createOpportunity(string $d,int $actor,array $in,string $ip):string{$this->permission($actor,$d==='career'?'jobs.post':'bursaries.post');$data=$this->validateOpportunity($d,$in);$ref=PublicReference::make($d==='career'?'JOB':'BUR');return$this->tx(function()use($d,$actor,$data,$ref,$ip){$id=$this->repo->createOpportunity($d,$data,$actor,$ref);$this->audits->record($actor,$d.'.opportunity_created',$d.'_opportunity',$id,$ip);return$ref;});}
private function validateOpportunity(string $d,array $in):array{if($d==='career'){$data=['title'=>$this->text($in,'title',3,255),'organisation'=>$this->text($in,'organisation',2,255),'location'=>trim((string)($in['location']??'')),'province_id'=>(int)($in['province_id']??0),'profession_id'=>(int)($in['profession_id']??0),'employment_type'=>$this->text($in,'employment_type',2,40),'work_arrangement'=>trim((string)($in['work_arrangement']??'')),'summary'=>$this->text($in,'summary',10,500),'description'=>$this->text($in,'description',20,10000),'requirements'=>$this->text($in,'requirements',10,10000),'application_instructions'=>trim((string)($in['application_instructions']??'')),'external_url'=>trim((string)($in['external_url']??'')),'closing_date'=>$this->date((string)($in['closing_date']??''),'Closing date')];if($data['external_url']!==''&&!filter_var($data['external_url'],FILTER_VALIDATE_URL))throw new DomainException('External URL must be a valid URL.');return$data;}$opening=$this->date((string)($in['opening_date']??''),'Opening date');$closing=$this->date((string)($in['closing_date']??''),'Closing date');if($closing<$opening)throw new DomainException('Closing date cannot precede opening date.');return['title'=>$this->text($in,'title',3,255),'provider'=>$this->text($in,'provider',2,255),'field_of_study'=>$this->text($in,'field_of_study',2,255),'description'=>$this->text($in,'description',20,10000),'eligibility_criteria'=>$this->text($in,'eligibility_criteria',10,10000),'benefits'=>$this->text($in,'benefits',2,5000),'study_level'=>$this->text($in,'study_level',2,100),'opening_date'=>$opening,'closing_date'=>$closing];}
public function opportunityStatus(string $d,int $actor,string $ref,string $to,string $ip):void{$this->permission($actor,$d==='career'?'jobs.moderate':'bursaries.moderate');$o=$this->repo->opportunity($d,$ref,true);if(!$o)throw new DomainException('Opportunity not found.');$this->statuses->assertOpportunity($o['status'],$to);if($to==='published'&&$o['closing_date']<gmdate('Y-m-d'))throw new DomainException('An expired opportunity cannot be published.');$this->tx(function()use($d,$actor,$o,$to,$ip){$this->repo->setOpportunityStatus($d,(int)$o['id'],$to,$actor);$this->audits->record($actor,$d.'.opportunity_'.$to,$d.'_opportunity',(int)$o['id'],$ip);});}
public function saveApplication(string $d,int $uid,string $oppRef,array $in,bool $submit,string $ip):array{$o=$this->repo->opportunity($d,$oppRef);if(!$o||$o['status']!=='published'||$o['closing_date']<gmdate('Y-m-d'))throw new DomainException('This opportunity is not open for applications.');$existing=$this->repo->applicationForUser($d,(int)$o['id'],$uid);if($existing&&$existing['status']!=='draft')return$existing;$data=$d==='career'?['cover_letter'=>$this->text($in,'cover_letter',$submit?20:0,5000),'experience_summary'=>$this->text($in,'experience_summary',$submit?10:0,5000)]:['institution'=>$this->text($in,'institution',$submit?2:0,255),'qualification'=>$this->text($in,'qualification',$submit?2:0,255),'study_level'=>$this->text($in,'study_level',$submit?1:0,100),'motivation'=>$this->text($in,'motivation',$submit?20:0,5000),'declaration_confirmed'=>!empty($in['declaration_confirmed'])?1:0];if($submit&&!$this->completion->calculate($this->profiles->byUserId($uid)??[])['complete'])throw new DomainException('Complete your member profile before submitting.');if($submit&&$d==='bursary'&&!$data['declaration_confirmed'])throw new DomainException('You must confirm the applicant declaration.');return$this->tx(function()use($d,$uid,$o,$existing,$data,$submit,$ip){if(!$existing){$ref=PublicReference::make($d==='career'?'CAP':'BAP');$id=$this->repo->createApplication($d,(int)$o['id'],$uid,$ref);$this->repo->event($d,$id,$uid,null,'draft','application.created','Draft created.');$existing=$this->repo->application($d,$ref,$uid);}else$id=(int)$existing['id'];$this->repo->saveApplication($d,$id,$data);if($submit){$this->statuses->assertApplication($d,'draft','submitted');$this->repo->transitionApplication($d,$id,'submitted',$uid);$this->repo->event($d,$id,$uid,'draft','submitted','application.submitted','Application submitted.');}$this->audits->record($uid,$d.'.application_'.($submit?'submitted':'saved'),$d.'_application',$id,$ip);return$this->repo->application($d,$existing['application_reference'],$uid);});}
public function withdraw(string $d,int $uid,string $ref,string $ip):void{$a=$this->repo->application($d,$ref,$uid);if(!$a)throw new DomainException('Application not found.');$this->statuses->assertApplication($d,$a['status'],'withdrawn');$this->tx(function()use($d,$uid,$a,$ip){$this->repo->transitionApplication($d,(int)$a['id'],'withdrawn',$uid);$this->repo->event($d,(int)$a['id'],$uid,$a['status'],'withdrawn','application.withdrawn','Withdrawn by applicant.');$this->audits->record($uid,$d.'.application_withdrawn',$d.'_application',(int)$a['id'],$ip);});}
public function review(string $d,int $actor,string $ref,string $to,string $reason,string $private,string $ip):void{$this->permission($actor,$d==='career'?'jobs.moderate':'bursaries.moderate');$a=$this->repo->application($d,$ref);if(!$a)throw new DomainException('Application not found.');$this->statuses->assertApplication($d,$a['status'],$to);$reason=trim($reason);$private=trim($private);if($to==='unsuccessful'&&mb_strlen($reason)<5)throw new DomainException('An applicant-visible unsuccessful reason is required.');if(mb_strlen($reason)>1000||mb_strlen($private)>2000)throw new DomainException('Review notes are too long.');$this->tx(function()use($d,$actor,$a,$to,$reason,$private,$ip){$this->repo->transitionApplication($d,(int)$a['id'],$to,$actor,$reason?:null,$private?:null);$this->repo->event($d,(int)$a['id'],$actor,$a['status'],$to,'application.'.$to,$to==='under_review'?null:($reason?:'Status updated.'));$this->audits->record($actor,$d.'.application_'.$to,$d.'_application',(int)$a['id'],$ip);});}}
